import { test, expect } from '@playwright/test';

test.describe('Notification Panel Slide In', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display notification panel with success message when triggered', async ({ page }) => {
    // Verify notification panel is not visible initially
    const notificationPanel = page.getByRole('region', { name: /notification/i });
    await expect(notificationPanel).not.toBeVisible();

    // Click the success notification button
    const successButton = page.getByRole('button', { name: /success/i });
    await expect(successButton).toBeVisible();
    await successButton.click();

    // Verify notification panel is now visible
    await expect(notificationPanel).toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/success message/i);
    await expect(successMessage).toBeVisible();

    // Verify close button is present
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify close button is clickable
    await expect(closeButton).toBeEnabled();

    // Verify notification panel slides in from the top
    const notificationPanelStyle = page.getByRole('region', { name: /notification/i }).evaluate((el) => {
      return window.getComputedStyle(el).getPropertyValue('transform');
    });
    await expect(notificationPanelStyle).toContain('translateY(-100%)');
  });

  test('should display error notification panel with error message when triggered', async ({ page }) => {
    // Verify notification panel is not visible initially
    const notificationPanel = page.getByRole('region', { name: /notification/i });
    await expect(notificationPanel).not.toBeVisible();

    // Click the error notification button
    const errorButton = page.getByRole('button', { name: /error/i });
    await expect(errorButton).toBeVisible();
    await errorButton.click();

    // Verify notification panel is now visible
    await expect(notificationPanel).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/error message/i);
    await expect(errorMessage).toBeVisible();

    // Verify close button is present
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify close button is clickable
    await expect(closeButton).toBeEnabled();

    // Verify notification panel slides in from the top
    const notificationPanelStyle = page.getByRole('region', { name: /notification/i }).evaluate((el) => {
      return window.getComputedStyle(el).getPropertyValue('transform');
    });
    await expect(notificationPanelStyle).toContain('translateY(-100%)');
  });
});
